<script>document.addEventListener('DOMContentLoaded',()=>{const cards=[...document.querySelectorAll('.catalog-card')],search=document.getElementById('catalog-search'),sort=document.getElementById('catalog-sort');let active='all';const update=()=>{const query=search.value.toLowerCase().trim();cards.forEach(card=>card.classList.toggle('hidden',!(active==='all'||card.dataset.category===active)||!card.dataset.name.includes(query)));const visible=cards.filter(card=>!card.classList.contains('hidden'));document.getElementById('catalog-empty').classList.toggle('hidden',visible.length!==0);const grid=document.getElementById('catalog-grid');visible.sort((a,b)=>sort.value==='az'?a.dataset.name.localeCompare(b.dataset.name):sort.value==='za'?b.dataset.name.localeCompare(a.dataset.name):0).forEach(card=>grid.appendChild(card));};document.querySelectorAll('.catalog-category').forEach(button=>button.addEventListener('click',()=>{active=button.dataset.category;document.querySelectorAll('.catalog-category').forEach(b=>b.classList.remove('bg-stone-900','text-white'));button.classList.add('bg-stone-900','text-white');update();}));search.addEventListener('input',update);sort.addEventListener('change',update);});</script>
